<?php require_once __DIR__.'/config/config.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$action=$_POST['action']??'';if($action==='remove')unset($_SESSION['cart'][$id]);elseif($action==='update')$_SESSION['cart'][$id]['qty']=max(1,(int)$_POST['qty']);go('cart.php');}$cart=$_SESSION['cart']??[];$items=[];$total=0;foreach($cart as $id=>$c){$s=$pdo->prepare('SELECT * FROM products WHERE id=? AND active=1');$s->execute([$id]);if($p=$s->fetch()){$p['qty']=$c['qty'];$p['line']=($p['sale_price']?:$p['price'])*$p['qty'];$total+=$p['line'];$items[]=$p;}}require 'includes/header.php';?><section class="section"><div class="container"><h1 class="mb-4" style="font-family:'Playfair Display'">Your Shopping Cart</h1><?php if(!$items):?><p>Your cart is empty. <a href="shop.php">Continue shopping</a></p><?php else:?><div class="row g-4"><div class="col-lg-8"><?php foreach($items as $p):?><div class="d-flex gap-3 align-items-center border-bottom py-3"><img src="<?=e($p['image_url'])?>" width="100" height="100" style="object-fit:cover"><div class="flex-grow-1"><b><?=e($p['name'])?></b><div><?=money($p['line'])?></div><form method="post" class="d-flex gap-2 mt-2"><?=csrf_field()?><input type="hidden" name="id" value="<?=$p['id']?>"><input type="number" class="form-control" style="max-width:90px" name="qty" min="1" value="<?=$p['qty']?>"><button name="action" value="update" class="btn btn-outline-secondary btn-sm">Update</button><button name="action" value="remove" class="btn btn-outline-danger btn-sm">Remove</button></form></div></div><?php endforeach;?></div><div class="col-lg-4"><div class="admin-card"><h4>Order Summary</h4><p>Subtotal <b class="float-end"><?=money($total)?></b></p><p>Shipping <b class="float-end">Calculated at checkout</b></p><hr><h5>Total <b class="float-end"><?=money($total)?></b></h5><a class="btn btn-gold w-100 mt-3" href="checkout.php">Proceed to Checkout</a></div></div></div><?php endif;?></div></section><?php require 'includes/footer.php';?>